import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CyZTVJbV.js";const g=JSON.parse('{"title":"kiwa v1.43 リリース — Edge / Serverless 深化 milestone + 縦深化 pair 第 12 新規 base pair 導入","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.43/zenn-article.md","filePath":"announcements/v1.43/zenn-article.md"}'),d={name:"announcements/v1.43/zenn-article.md"};function i(l,e,n,s,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="kiwa-v1-43-リリース-—-edge-serverless-深化-milestone-縦深化-pair-第-12-新規-base-pair-導入" tabindex="-1">kiwa v1.43 リリース — Edge / Serverless 深化 milestone + 縦深化 pair 第 12 新規 base pair 導入 <a class="header-anchor" href="#kiwa-v1-43-リリース-—-edge-serverless-深化-milestone-縦深化-pair-第-12-新規-base-pair-導入" aria-label="Permalink to &quot;kiwa v1.43 リリース — Edge / Serverless 深化 milestone + 縦深化 pair 第 12 新規 base pair 導入&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>kiwa v1.43 をリリースしました。 <strong>12 番目の縦深化 pair を新規導入</strong> — Edge / Serverless base at v1.43、 v1.37 Security 以来 5 milestone ぶりの新規 pair base。 3 例目 depth-4 record 達成 (v1.40 AI/LLM + v1.41 Payment + v1.42 Observability) 後の 5-milestone new-base cadence が完成しました。</p><h2 id="何が変わったか" tabindex="-1">何が変わったか <a class="header-anchor" href="#何が変わったか" aria-label="Permalink to &quot;何が変わったか&quot;">​</a></h2><h3 id="kiwa-lab-edge-v1-2-0-v1-1-0-→-v1-2-0-minor-bump" tabindex="-1"><code>@kiwa-lab/edge</code> v1.2.0 (v1.1.0 → v1.2.0 minor bump) <a class="header-anchor" href="#kiwa-lab-edge-v1-2-0-v1-1-0-→-v1-2-0-minor-bump" aria-label="Permalink to &quot;`@kiwa-lab/edge` v1.2.0 (v1.1.0 → v1.2.0 minor bump)&quot;">​</a></h3><p>既存の 8-axis base の上に、 8 個の advanced axis を追加しました。</p><ul><li><strong>cold-start</strong> — Serverless 関数の warm/cold path + provisioned concurrency をモデル化。 <code>startColdStartPool</code> + <code>invokeColdStart</code> + <code>preWarmInstance</code> + <code>evictExpired</code>。</li><li><strong>middleware-chain</strong> — Edge middleware pipeline (auth → rewrite → cache → transform + short-circuit)。 <code>startMiddlewareChain</code> + <code>enterMiddleware</code> + <code>rewriteRequest</code> + <code>shortCircuit</code> + <code>completeMiddleware</code>。</li><li><strong>kv-eventual-consistency</strong> — Read-your-writes + monotonic-reads の consistency 検知。 <code>startKvConsistency</code> + <code>recordWriteQuorum</code> + <code>observeRead</code> + <code>forceConvergence</code>。</li><li><strong>r2-multipart</strong> — Resumable multipart upload with per-part checksum verification。 <code>initiateMultipart</code> + <code>uploadPart</code> + <code>verifyChecksum</code> + <code>completeMultipart</code>。</li><li><strong>d1-read-replica</strong> — Primary-replica DB routing with lag detection + failover。 <code>startD1</code> + <code>writeToPrimary</code> + <code>readFromReplica</code> + <code>reportLag</code>。</li><li><strong>do-state-migration</strong> — DurableObject schema versioning + zero-downtime rollout + rollback。 <code>initiateMigration</code> + <code>bumpSchema</code> + <code>migrateInstance</code> + <code>completeRollout</code> + <code>rollbackMigration</code>。</li><li><strong>websocket-hibernation</strong> — Cloudflare Workers / Vercel Edge の WebSocket hibernation model。 <code>startHibernationSession</code> + <code>hibernate</code> + <code>resume</code> + <code>restoreState</code> + <code>completeReconnect</code>。</li><li><strong>global-routing</strong> — Anycast + geo + latency-based failover routing。 <code>startRoutingPool</code> + <code>receiveAnycast</code> + <code>matchGeo</code> + <code>selectByLatency</code> + <code>markUnhealthy</code>。</li></ul><p>3 platform (cloudflare / vercel / deno) × 16 axis (8 v0.2 base + 8 v1.2 advanced) = 48 cell の fidelity grid。</p><h3 id="_3-dogfood-app-を新規追加" tabindex="-1">3 dogfood app を新規追加 <a class="header-anchor" href="#_3-dogfood-app-を新規追加" aria-label="Permalink to &quot;3 dogfood app を新規追加&quot;">​</a></h3><ul><li><code>examples/dogfood-edge-serverless-cold-start-app</code> — 64 tests。 cold / warm / provisioned 3 axis × 3 platform mock/real adapter + fidelity harness。</li><li><code>examples/dogfood-edge-durable-object-migration-app</code> — 60 tests。 schema-bump / data-migrate / rollout 3 axis × 3 platform mock/real adapter + fidelity harness。</li><li><code>examples/dogfood-edge-global-routing-app</code> — 60 tests。 anycast-routing / geo-matching / replica-affinity 3 axis × 3 platform mock/real adapter + fidelity harness。</li></ul><p>各 dogfood は real driver env-gate (<code>KIWA_MODE=real</code> + <code>EDGE_*_STACK_READY=1</code> + <code>KIWA_EDGE_*_URL</code>) を持ち、 fidelity harness が実 Cloudflare Workers + Vercel Edge + AWS Lambda + Deno Deploy backend に対して opt-in で走査可能。</p><h3 id="_3-tutorial-を新規追加" tabindex="-1">3 tutorial を新規追加 <a class="header-anchor" href="#_3-tutorial-を新規追加" aria-label="Permalink to &quot;3 tutorial を新規追加&quot;">​</a></h3><ul><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/94-serverless-cold-start" target="_blank" rel="noreferrer">Tutorial 94 — Serverless cold-start</a></strong> — cold path + warm pool + provisioned concurrency + latency observability walkthrough。</li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/95-durable-object-migration" target="_blank" rel="noreferrer">Tutorial 95 — DurableObject state migration</a></strong> — schema versioning + data migrate + zero-downtime rollout + rollback walkthrough。</li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/96-global-routing" target="_blank" rel="noreferrer">Tutorial 96 — Global routing</a></strong> — Anycast + geo matching + latency-based failover + D1 read replica affinity walkthrough。</li></ul><h2 id="_21-milestone-連続-snippet-validation-streak-達成" tabindex="-1">21 milestone 連続 snippet validation streak 達成 <a class="header-anchor" href="#_21-milestone-連続-snippet-validation-streak-達成" aria-label="Permalink to &quot;21 milestone 連続 snippet validation streak 達成&quot;">​</a></h2><p>v1.23 から v1.43 まで、 21 milestone 連続で tutorial code snippet の validation test を kiwa monorepo 内に配置しています。 docs と API の drift を merge 時に自動検知する仕組みが、 21 milestone 続く streak になりました。</p><h2 id="縦深化-pair-pattern-grid" tabindex="-1">縦深化 pair pattern grid <a class="header-anchor" href="#縦深化-pair-pattern-grid" aria-label="Permalink to &quot;縦深化 pair pattern grid&quot;">​</a></h2><p>現在 12 pair が記録されています。</p><table tabindex="0"><thead><tr><th>Pair #</th><th>Domain</th><th>Path</th><th>Depth</th></tr></thead><tbody><tr><td>1</td><td>Auth</td><td>v1.21→v1.22</td><td>2</td></tr><tr><td>2</td><td>Realtime</td><td>v1.13→v1.28</td><td>2</td></tr><tr><td>3</td><td>Streaming</td><td>v1.20→v1.31</td><td>2</td></tr><tr><td>4</td><td>Database</td><td>v1.14→v1.32</td><td>2</td></tr><tr><td>5</td><td>Payment</td><td>v1.14→v1.19→v1.33→v1.41</td><td>4</td></tr><tr><td>6</td><td>Frontend</td><td>v1.16→v1.34</td><td>2</td></tr><tr><td>7</td><td>Observability</td><td>v1.14→v1.17→v1.35→v1.42</td><td>4</td></tr><tr><td>8</td><td>Search</td><td>v1.14→v1.15→v1.36</td><td>3</td></tr><tr><td>9</td><td>Security</td><td>v1.37→v1.39</td><td>2</td></tr><tr><td>10</td><td>AI/LLM</td><td>v1.12→v1.15→v1.38→v1.40</td><td>4</td></tr><tr><td>11</td><td>Security base</td><td>v1.37</td><td>1</td></tr><tr><td><strong>12</strong></td><td><strong>Edge / Serverless</strong></td><td><strong>v1.43 (new base)</strong></td><td><strong>1</strong></td></tr></tbody></table><h2 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/edge@^1.2</span></span></code></pre></div><p>Additive-only。 breaking change はありません。</p><h2 id="migration-guide" tabindex="-1">Migration guide <a class="header-anchor" href="#migration-guide" aria-label="Permalink to &quot;Migration guide&quot;">​</a></h2><p><a href="https://cardene777.github.io/kiwa/migrations/v1.42-to-v1.43" target="_blank" rel="noreferrer">v1.42 → v1.43 migration guide</a></p><h2 id="次に何が来るか" tabindex="-1">次に何が来るか <a class="header-anchor" href="#次に何が来るか" aria-label="Permalink to &quot;次に何が来るか&quot;">​</a></h2><p>v1.44+ で 5-milestone cadence で新規 pair base の導入が続きます。 Edge / Serverless の次の III 深化 target は v1.62 前後 (4 段拡張 pattern の III 深化 = base +19 milestone)。 pair 9-11 が確立した pattern に沿った深化を予定しています。</p>',25)])])}const v=t(d,[["render",i]]);export{g as __pageData,v as default};
